// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: montserratFamily } = loadMontserrat();



export type VlogLowerThirdProps = Record<string, any>;

const VlogLowerThird: React.FC<VlogLowerThirdProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 5,
  vlogText = "VLOG",
  vlogNumber = 1,
  numberPrefix = "#",
  textColor = "#ffffff",
  accentColor = "#FF0055",
  plateColor = "#111111",
  scale = 1,
  offsetX = 150,
  offsetY = 150,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Handle background transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Frame timing calculation
  const totalFrames = durationInSeconds * fps;
  const outroStart = totalFrames - 40; 

  // --- Staggered Animation Logic ---
  // The intro sequence animates forward, while the outro reverses the sequence 
  // perfectly by shifting the outgoing springs.
  
  const lineProgress =
    spring({ frame, fps, config: { damping: 14 } }) -
    spring({ frame: frame - outroStart - 20, fps, config: { damping: 14 } });

  const plateProgress =
    spring({ frame: frame - 5, fps, config: { damping: 14 } }) -
    spring({ frame: frame - outroStart - 15, fps, config: { damping: 14 } });

  const numBoxProgress =
    spring({ frame: frame - 10, fps, config: { damping: 14 } }) -
    spring({ frame: frame - outroStart - 10, fps, config: { damping: 14 } });

  const textProgress =
    spring({ frame: frame - 15, fps, config: { damping: 12 } }) -
    spring({ frame: frame - outroStart - 5, fps, config: { damping: 12 } });

  const numTextProgress =
    spring({ frame: frame - 20, fps, config: { damping: 12 } }) -
    spring({ frame: frame - outroStart, fps, config: { damping: 12 } });

  // Formatting helpers
  const displayNum = vlogNumber.toString().padStart(2, "0");

  const safeOpacity = (val: number) =>
    interpolate(val, [0, 1], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          position: "absolute",
          left: offsetX,
          bottom: offsetY,
          display: "flex",
          flexDirection: "column",
          // Adding a clean skew commonly found in professional vlog graphics
          transform: `scale(${scale}) skewX(-10deg)`,
          transformOrigin: "bottom left",
          filter: "drop-shadow(0px 20px 30px rgba(0,0,0,0.3))",
          transition: "none",
        }}
      >
        {/* Top Accent Line */}
        <div
          style={{
            height: 8,
            backgroundColor: accentColor,
            width: "100%",
            clipPath: `inset(0 ${100 - lineProgress * 100}% 0 0)`,
            marginBottom: 8,
            transition: "none",
          }}
        />

        {/* Plates Row */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            transition: "none",
          }}
        >
          {/* Main Vlog Text Plate */}
          <div
            style={{
              backgroundColor: plateColor,
              padding: "24px 48px",
              clipPath: `inset(0 ${100 - plateProgress * 100}% 0 0)`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transition: "none",
            }}
          >
            {/* The text wrapper un-skews the content so the letters remain perfectly upright */}
            <div
              style={{
                transform: `translateY(${interpolate(textProgress, [0, 1], [100, 0])}%) skewX(10deg)`,
                opacity: safeOpacity(textProgress),
                transition: "none",
              }}
            >
              <span
                style={{
                  fontFamily: interFamily,
                  fontWeight: 900,
                  fontSize: 80,
                  color: textColor,
                  textTransform: "uppercase",
                  lineHeight: 1,
                  display: "block",
                }}
              >
                {vlogText}
              </span>
            </div>
          </div>

          {/* Number Plate (Right Side) */}
          <div
            style={{
              backgroundColor: accentColor,
              padding: "24px 48px",
              clipPath: `inset(0 ${100 - numBoxProgress * 100}% 0 0)`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transition: "none",
            }}
          >
            <div
              style={{
                transform: `translateY(${interpolate(numTextProgress, [0, 1], [100, 0])}%) skewX(10deg)`,
                opacity: safeOpacity(numTextProgress),
                transition: "none",
              }}
            >
              <span
                style={{
                  fontFamily: montserratFamily,
                  fontWeight: 900,
                  fontSize: 80,
                  color: textColor,
                  lineHeight: 1,
                  display: "block",
                }}
              >
                {numberPrefix}
                {displayNum}
              </span>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default VlogLowerThird;